245	        Long next = jdbc.queryForObject(
246	                "SELECT COALESCE(MAX(id), 0) + 1 FROM " + table, Long.class);
247	        jdbc.execute("ALTER TABLE " + table + " ALTER COLUMN id RESTART WITH " + next);
248	    }
