======ClientRepository======
package net.officefloor.hq.app;

import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;

/** Data access for {@link Client} rows (JdbcTemplate over the H2 schema in V1__clients.sql). */
@Repository
public class ClientRepository {

    private final JdbcTemplate jdbc;

    public ClientRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * List clients. Archived clients are hidden — that is what keeps a tucked-away client off the
     * main list (and the name search that filters it) while its row is retained.
     */
    public List<Client> findAll() {
        return jdbc.query(
                "SELECT id, name, email FROM clients WHERE archived = FALSE ORDER BY id",
                (rs, i) -> new Client(rs.getLong("id"), rs.getString("name"), rs.getString("email")));
    }

    /**
     * Clients whose name matches the global search term (case-insensitive substring). Archived
     * clients stay hidden, matching the plain list. A blank term matches nothing — the global
     * search only surfaces results once something is typed.
     */
    public List<Client> searchByName(String term) {
        if (term == null || term.isBlank()) {
            return List.of();
        }
        return jdbc.query(
                "SELECT id, name, email FROM clients"
                        + " WHERE archived = FALSE AND LOWER(name) LIKE ? ORDER BY id",
                (rs, i) -> new Client(rs.getLong("id"), rs.getString("name"), rs.getString("email")),
                "%" + term.trim().toLowerCase() + "%");
    }

    /** Look up one client, or null when there is no such row. */
    public Client findById(long id) {
        List<Client> rows = jdbc.query(
                "SELECT id, name, email FROM clients WHERE id = ?",
                (rs, i) -> new Client(rs.getLong("id"), rs.getString("name"), rs.getString("email")),
                id);
        return rows.isEmpty() ? null : rows.get(0);
    }

    /**
     * List the archived (tucked-away) clients, so they can be reviewed and brought back. The inverse
     * of {@link #findAll()}: only rows flagged archived, in the same id order.
     */
    public List<Client> findArchived() {
        return jdbc.query(
                "SELECT id, name, email FROM clients WHERE archived = TRUE ORDER BY id",
                (rs, i) -> new Client(rs.getLong("id"), rs.getString("name"), rs.getString("email")));
    }

    /** Tuck a client away: flag it archived so it drops off the lists but its row is retained. */
    public boolean archive(long id) {
        return jdbc.update("UPDATE clients SET archived = TRUE WHERE id = ?", id) > 0;
    }

    /** Bring an archived client back: clear the flag so it returns to the main list and search. */
    public boolean restore(long id) {
        return jdbc.update("UPDATE clients SET archived = FALSE WHERE id = ?", id) > 0;
    }

    /** Correct a client's name/email. Returns the updated row, or null when there is no such row. */
    public Client update(long id, String name, String email) {
        int rows = jdbc.update("UPDATE clients SET name = ?, email = ? WHERE id = ?", name, email, id);
        return rows > 0 ? new Client(id, name, email) : null;
    }

    /**
     * Whether a client already uses this email. Two clients cannot share an email, so a create must
     * be rejected when one exists (defence alongside the {@code clients_email_unique} constraint in
     * V27). Considers every row, including archived ones — the email is still taken.
     */
    public boolean existsByEmail(String email) {
        Integer count = jdbc.queryForObject(
                "SELECT COUNT(*) FROM clients WHERE email = ?", Integer.class, email);
        return count != null && count > 0;
    }

    /**
     * Whether a client OTHER than {@code id} already uses this email. Lets a client keep its own
     * address on an edit while still rejecting a collision with a different client (mirrors the
     * {@code clients_email_unique} constraint in V27).
     */
    public boolean existsByEmailForOther(String email, long id) {
        Integer count = jdbc.queryForObject(
                "SELECT COUNT(*) FROM clients WHERE email = ? AND id <> ?", Integer.class, email, id);
        return count != null && count > 0;
    }

    public Client create(String name, String email) {
        KeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            var ps = con.prepareStatement(
                    "INSERT INTO clients (name, email) VALUES (?, ?)", new String[] {"id"});
            ps.setString(1, name);
            ps.setString(2, email);
            return ps;
        }, keys);
        return new Client(keys.getKey().longValue(), name, email);
    }
}
======DashboardRepository======
package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** Read-only aggregate queries backing the home dashboard (counts + outstanding total). */
@Repository
public class DashboardRepository {

    private final JdbcTemplate jdbc;

    public DashboardRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public DashboardSummary summary() {
        long clients = jdbc.queryForObject("SELECT COUNT(*) FROM clients", Long.class);
        long projects = jdbc.queryForObject("SELECT COUNT(*) FROM projects", Long.class);
        // Money still owed = for every issued invoice (stored status SENT), its discounted amount
        // (the sum of its line items qty * unit_price, with the invoice's discount_pct taken off)
        // minus whatever has been paid against it. Amount is derived from line items (V13) and the
        // discount from discount_pct (V29), so what is owed reflects the discount everywhere. DRAFT
        // invoices are not yet issued and VOID invoices were cancelled, so both are excluded (their
        // stored status is not SENT). COALESCE keeps the total at 0.00 (never null) when nothing is
        // outstanding.
        BigDecimal outstanding = jdbc.queryForObject(
                "SELECT COALESCE(SUM("
                        + "COALESCE((SELECT SUM(li.qty * li.unit_price) FROM line_items li"
                        + " WHERE li.invoice_id = i.id), 0) * (100 - i.discount_pct) / 100"
                        + " - COALESCE((SELECT SUM(pm.amount) FROM payments pm"
                        + " WHERE pm.invoice_id = i.id), 0)), 0)"
                        + " FROM invoices i WHERE i.status = 'SENT'",
                BigDecimal.class);
        // Overdue = invoices that have been SENT and whose due date has already passed relative to
        // the dashboard's reference date. That date is seeded (dashboard_settings.as_of) so the
        // count is deterministic under test; when unset we fall back to the current date. DRAFT
        // invoices are not yet issued so they are never overdue.
        LocalDate asOf = jdbc.query(
                "SELECT as_of FROM dashboard_settings ORDER BY id LIMIT 1",
                rs -> rs.next() && rs.getDate("as_of") != null
                        ? rs.getDate("as_of").toLocalDate() : null);
        if (asOf == null) {
            asOf = LocalDate.now();
        }
        long overdue = jdbc.queryForObject(
                "SELECT COUNT(*) FROM invoices"
                        + " WHERE status = 'SENT' AND due_date IS NOT NULL AND due_date < ?",
                Long.class, Date.valueOf(asOf));
        return new DashboardSummary(clients, projects, outstanding, overdue);
    }

    // What is still owed on an invoice, worked out the same way "due" is everywhere else
    // (ClientOutstandingRepository / InvoiceRepository): its line-item total (qty * unit_price), less
    // the discount (V29), plus tax (V30), minus what has been paid. DRAFT invoices (not yet issued)
    // and VOID invoices (cancelled) do not count toward money owed (V24).
    private static final String DUE =
            "(COALESCE((SELECT SUM(li.qty * li.unit_price) FROM line_items li"
                    + " WHERE li.invoice_id = i.id), 0)"
                    + " * (100 - i.discount_pct) / 100 * (100 + i.tax_pct) / 100"
                    + " - COALESCE((SELECT SUM(pm.amount) FROM payments pm"
                    + " WHERE pm.invoice_id = i.id), 0))";

    /**
     * The home screen's top clients ranked by how much they still owe (highest first), capped at
     * {@code limit}. Non-archived clients only; a client with no owed invoices totals 0.00. Ties break
     * by id so the order is deterministic under test.
     */
    public List<TopClient> topClients(int limit) {
        return jdbc.query(
                "SELECT c.id AS client_id, c.name AS name,"
                        + " COALESCE(SUM(" + DUE + "), 0) AS outstanding"
                        + " FROM clients c"
                        + " LEFT JOIN projects p ON p.client_id = c.id"
                        + " LEFT JOIN invoices i ON i.project_id = p.id"
                        + " AND i.status NOT IN ('DRAFT', 'VOID')"
                        + " WHERE c.archived = FALSE"
                        + " GROUP BY c.id, c.name"
                        + " ORDER BY outstanding DESC, c.id ASC"
                        + " LIMIT ?",
                (rs, n) -> new TopClient(
                        rs.getLong("client_id"), rs.getString("name"),
                        rs.getBigDecimal("outstanding")),
                limit);
    }
}
