                    + " WHEN i.status = 'DRAFT' THEN 'DRAFT'"
                    + " WHEN " + AMOUNT_SUM + " > 0 AND " + PAID_SUM + " >= " + AMOUNT_SUM
                    + " THEN 'PAID'"
                    + " WHEN " + PAID_SUM + " > 0 THEN 'PARTIAL'"
                    + " ELSE 'SENT' END";

    public List<Invoice> findByProject(long projectId) {
        return jdbc.query(
