                        + " " + DERIVED_STATUS + " AS status, i.issued_date, i.due_date, i.discount_pct, i.tax_pct, " + CURRENCY + " AS currency"
                        + " FROM invoices i WHERE i.project_id = ? ORDER BY i.id",
