            onClick={() => openInvoice(null)}
          >
            Back to invoices
          </button>
          <InvoiceDetail invoiceId={openInvoiceId} />
        </>
      ) : (
        <>
      <div data-testid="invoice-controls">
        <button type="button" data-testid="invoice-sort-due" onClick={sortByDue}>
          Sort by due date
        </button>
      </div>

      <table data-testid="project-invoices-table">
        <thead>
          <tr>
            <th>Amount</th>
            <th>Still due</th>
            <th>Issued</th>
            <th>Due</th>
            <th>Status</th>
            <th />
          </tr>
        </thead>
        <tbody>
          {invoices.map((inv) => (
